def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.popleft()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        q.append((yy, xx))
            components.append((color, cells))

    # Use the largest straight component as the color marker.
    guides = []
    for color, cells in components:
        ys = [y for y, x in cells]
        xs = [x for y, x in cells]
        if len(cells) >= 5 and (min(ys) == max(ys) or min(xs) == max(xs)):
            guides.append((color, cells))
    if not guides:
        return [row[:] for row in grid]
    guide_color, guide_cells = max(guides, key=lambda z: len(z[1]))

    # Recolor the closest separate object, excluding isolated noise pixels.
    targets = [(color, cells) for color, cells in components
               if color != guide_color and len(cells) >= 2]
    if not targets:
        return [row[:] for row in grid]

    def distance(cells):
        return min(abs(y - gy) + abs(x - gx)
                   for y, x in cells for gy, gx in guide_cells)

    target_color, target_cells = min(
        targets, key=lambda item: (distance(item[1]), -len(item[1]))
    )
    out = [row[:] for row in grid]
    for y, x in target_cells:
        out[y][x] = guide_color
    return out
